module PLL (
    input wire clk_in,
    input wire reset,
    input wire [1:0] control,
    output reg clk_out
);
    reg [1:0] state;

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            state <= 2'b00;
            clk_out <= 1'b0;
        end else begin
            case (control)
                2'b00: begin
                    clk_out <= clk_in;
                    state <= 2'b00;
                end
                2'b01: begin
                    clk_out <= clk_in;
                    state <= 2'b01;
                end
                2'b10: begin
                    clk_out <= ~clk_in;
                    state <= 2'b10;
                end
                2'b11: begin
                    clk_out <= ~clk_in;
                    state <= 2'b11;
                end
                default: begin
                    clk_out <= 1'b0;
                    state <= 2'b00;
                end
            endcase
        end
    end
endmodule

