module pwm_generator (
    input clk,
    input [7:0] duty_cycle, // Duty cycle in percentage (0-100)
    output reg pwm_out
);
    reg [7:0] counter;

    always @(posedge clk) begin
        if (counter < 255) begin
            counter <= counter + 1;
        end else begin
            counter <= 0;
        end

        if (counter < (duty_cycle * 255) / 100) begin
            pwm_out <= 1;
        end else begin
            pwm_out <= 0;
        end
    end
endmodule

