module deserializer_32bit (  
    input clk,  
    input rst_n,  
    input [3:0] data_in,  
    input data_valid,  
    output reg [31:0] data_out,  
    output reg data_out_valid  
);  
    reg [2:0] count; // Count for 8 cycles  
    reg [31:0] shift_reg;  

    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n) begin  
            count <= 3'b000;  
            shift_reg <= 32'b0;  
            data_out <= 32'b0;  
            data_out_valid <= 1'b0;  
        end else if (data_valid) begin  
            if (count < 3'b111) begin // Less than 8 cycles  
                shift_reg <= {shift_reg[27:0], data_in}; // Shift in new data  
                count <= count + 1;  
                data_out_valid <= 1'b0;  
            end else begin  
                data_out <= shift_reg;  
                data_out_valid <= 1'b1;  
                count <= 3'b000; // Reset count for next deserialization  
                shift_reg <= 32'b0;  
            end  
        end  
    end  
endmodule

