module mersenne_twister (
    input wire clk,
    input wire reset,
    input wire [31:0] seed,
    output reg [31:0] random_number
);
    reg [31:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= seed;
            random_number <= 0;
        end else begin
            // Simple LFSR-like update for the state
            state <= {state[30:0], state[31] ^ state[21] ^ state[1] ^ state[0]}; // Example feedback
            random_number <= state;
        end
    end
endmodule

