        integer i;
        begin
            expected_frame = {1'b1, expected_data, 1'b0};


            wait(tx == 0);


            repeat (2604) @(posedge clk);

            for (i = 0; i < 10; i = i + 1) begin
                captured_frame[i] = tx;
