module butterworth_filter (
    input clk,
    input reset,
    input [3:0] in_signal,
    output reg [3:0] out_signal
);
    reg [3:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 4'b0000;
            out_signal <= 4'b0000;
        end else begin
            // Simple state transition for Butterworth filter
            state <= in_signal; // Directly pass input to state for simplicity
            out_signal <= (state + 4'b0001) >> 1; // Emulate a simple low-pass filter
        end
    end
endmodule

