module spi_controller (  
    input wire clk,  
    input wire reset,  
    input wire cs,  
    input wire mosi,  
    input wire sck,  
    output reg miso  
);  

    reg [7:0] data_in;  
    reg [7:0] data_out;  
    reg [2:0] bit_cnt;  
    reg transmitting;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            data_in <= 8'b0;  
            data_out <= 8'b0;  
            bit_cnt <= 3'b0;  
            transmitting <= 1'b0;  
            miso <= 1'b0;  
        end else if (cs == 1'b0) begin  
            if (sck) begin  
                if (bit_cnt < 3'd8) begin  
                    data_in <= {data_in[6:0], mosi};  
                    bit_cnt <= bit_cnt + 1;  
                end else begin  
                    transmitting <= 1'b1;  
                    data_out <= data_in;  
                    bit_cnt <= 3'b0;  
                end  
                miso <= data_out[7];  
                data_out <= {data_out[6:0], 1'b0};  
            end  
        end else begin  
            transmitting <= 1'b0;  
            bit_cnt <= 3'b0;  
            miso <= 1'b0;  
        end  
    end  
endmodule

