module voltage_sensor (  
    input wire clk,  
    input wire reset,  
    input wire [7:0] voltage,  
    output reg alert  
);  
    reg [1:0] state, next_state;  
    parameter THRESHOLD = 8'hA0;  
    parameter ALERT_DELAY = 2'b11;  

    always @(posedge clk or posedge reset) begin  
        if (reset)  
            state <= 2'b00;  
        else  
            state <= next_state;  
    end  

    always @(*) begin  
        case (state)  
            2'b00: next_state = (voltage > THRESHOLD) ? 2'b01 : 2'b00;  
            2'b01: next_state = (voltage > THRESHOLD) ? 2'b10 : 2'b00;  
            2'b10: next_state = (voltage > THRESHOLD) ? ALERT_DELAY : 2'b00;  
            default: next_state = 2'b00;  
        endcase  
    end  

    always @(posedge clk or posedge reset) begin  
        if (reset)  
            alert <= 0;  
        else if (state == ALERT_DELAY)  
            alert <= 1;  
        else  
            alert <= 0;  
    end  
endmodule

