module pitch_detection(  
    input clk,  
    input reset,  
    input [7:0] signal_in,  
    output reg pitch_detected  
);  

parameter THRESHOLD = 8'd150;  
parameter DETECTION_TIME = 4'd5;  

reg [3:0] count;  
reg above_threshold;  

always @(posedge clk or posedge reset) begin  
    if (reset) begin  
        pitch_detected <= 0;  
        count <= 0;  
        above_threshold <= 0;  
    end else begin  
        if (signal_in > THRESHOLD) begin  
            above_threshold <= 1;  
            count <= count + 1;  
            if (count >= DETECTION_TIME) begin  
                pitch_detected <= 1;  
            end  
        end else begin  
            above_threshold <= 0;  
            count <= 0;  
            pitch_detected <= 0;  
        end  
    end  
end  
endmodule

