module fractional_n_divider (  
    input wire clk_in,  
    input wire reset,  
    input wire [3:0] N,  // Fractional division value  
    output reg clk_out  
);  
    reg [3:0] count;  
    reg [3:0] div;  

    always @(posedge clk_in or posedge reset) begin  
        if (reset) begin  
            count <= 0;  
            clk_out <= 0;  
            div <= N;  
        end else begin  
            if (count < div) begin  
                count <= count + 1;  
            end else begin  
                clk_out <= ~clk_out;  
                count <= 0;  
            end  
        end  
    end  
endmodule

