module rsa_encryptor (  
    input wire clk,  
    input wire reset,  
    input wire [7:0] plaintext,  
    input wire [7:0] exponent,  
    input wire [7:0] modulus,  
    output reg [15:0] ciphertext  
);  
    reg [15:0] result;  
    reg [7:0] exp;  
    reg [15:0] base;  
    reg [3:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            result <= 16'd1;  
            exp <= exponent;  
            base <= plaintext;  
            count <= 4'd0;  
        end else begin  
            if (count < 8) begin  
                if (exp[count])  
                    result <= (result * base) % modulus;  
                base <= (base * base) % modulus;  
                count <= count + 1;  
            end else begin  
                ciphertext <= result;  
            end  
        end  
    end  
endmodule

